import { NextRequest, NextResponse } from "next/server";

// Streams a workbook generated by the EIOPA agent (rag_service/generated) to the browser.
// Same whitelist as the Python side: only names the service creates, so no path can be smuggled in.
const SAFE_NAME = /^[A-Za-z0-9_.-]+\.xlsx$/;
const XLSX = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

export async function GET(_request: NextRequest, { params }: { params: Promise<{ name: string }> }) {
  const { name } = await params;
  if (!SAFE_NAME.test(name)) return NextResponse.json({ error: "Nom de fichier invalide." }, { status: 400 });
  const base = process.env.RAG_SERVICE_URL ?? "http://127.0.0.1:8001";
  try {
    const upstream = await fetch(`${base}/api/eiopa-agent/files/${encodeURIComponent(name)}`, { signal: AbortSignal.timeout(30000) });
    if (!upstream.ok) return NextResponse.json({ error: upstream.status === 404 ? "Fichier introuvable (il a peut-être été supprimé du serveur)." : `Service Python : HTTP ${upstream.status}` }, { status: upstream.status === 404 ? 404 : 502 });
    return new Response(await upstream.arrayBuffer(), { headers: { "Content-Type": XLSX, "Content-Disposition": `attachment; filename="${name}"` } });
  } catch (error) {
    return NextResponse.json({ error: `Service Python injoignable : ${error instanceof Error ? error.message : String(error)}` }, { status: 502 });
  }
}
